+    protected void cancelOutstandingReads(IOUringIoRegistration registration, int numOutstandingReads) {
+        // TODO: implement me
+    }
+
+    @Override
+    protected void cancelOutstandingWrites(IOUringIoRegistration registration, int numOutstandingWrites) {
