+        private final class WriteProcessor implements ChannelOutboundBuffer.MessageProcessor {
+            private int written;
+
+            @Override
+            public boolean processMessage(Object msg) {
+                if (scheduleWrite(msg, true)) {
+                    written++;
+                    return true;
+                }
+                return false;
+            }
