+
+    public static final Runnable EMPTY_RUNNABLE = () -> {
+    };
+
+    @BeforeAll
+    public static void loadJNI() {
+        assumeTrue(IOUring.isAvailable());
+    }
+
+    protected IoHandlerFactory newIoHandlerFactory() {
+        return IOUringHandler.newFactory();
