+    AbstractIOUringChannel(Channel parent, LinuxSocket fd, SocketAddress remote) {
+        super(parent);
+        this.socket = checkNotNull(fd, "fd");
+        this.active = true;
+
+        // Directly cache the remote and local addresses
+        // See https://github.com/netty/netty/issues/2359
