+        if (acceptId != 0) {
+            assert numOutstandingReads == 1;
+            IOUringIoOps ops = IOUringIoOps.newAsyncCancel(fd().intValue(), 0, acceptId, Native.IORING_OP_ACCEPT);
+            registration.submit(ops);
+        }
