+        EventLoopGroup group =  new MultiThreadIoEventLoopGroup(1, newIoHandlerFactory());
+        try {
+            EventLoop loop = group.next();
+            loop.submit(EMPTY_RUNNABLE).sync();
+            loop.submit(EMPTY_RUNNABLE).sync();
+            loop.submit(EMPTY_RUNNABLE).sync();
+            loop.submit(EMPTY_RUNNABLE).sync();
+        } finally {
+            group.shutdownGracefully();
